), metadata AS (
  UPDATE universities u SET institution_type=coalesce(u.institution_type,s.institution_type),
    source_url=coalesce(u.source_url,'https://enseignementsuperieur.gouv.bj/uploads/document_actualite/07ccfec01c103dab63756ab2b15455be.pdf')
  FROM source s, countries c
  WHERE c.code='BEN' AND u.country_id=c.id AND u.tenant_id IS NULL
  AND (lower(u.name)=lower(s.name) OR
       (s.short_name IS NOT NULL AND (lower(u.short_name)=lower(s.short_name) OR lower(u.name)=lower(s.short_name))))
  RETURNING u.id
)
INSERT INTO universities(name,short_name,country_id,city_id,institution_type,description,source_url,verified)
SELECT s.name,s.short_name,c.id,NULL,s.institution_type,s.description,'https://enseignementsuperieur.gouv.bj/uploads/document_actualite/07ccfec01c103dab63756ab2b15455be.pdf',false
FROM source s CROSS JOIN countries c
WHERE c.code = 'BEN' AND NOT c.deleted
AND NOT EXISTS (
  SELECT 1 FROM universities u WHERE u.country_id=c.id AND u.tenant_id IS NULL
  AND (lower(u.name)=lower(s.name) OR
       (s.short_name IS NOT NULL AND (lower(u.short_name)=lower(s.short_name) OR lower(u.name)=lower(s.short_name))))
);
